        vm.warp(SAFE_TIMESTAMP_BASE + lockPeriod - 1); // 1 sec before unlock
        uint256 preWithdrawContractBalance = address(moneyBox).balance;
        uint256 preWithdrawUserBalance = user.balance;
        vm.prank(user);
        moneyBox.Collect(depositAmount);
        assertEq(address(moneyBox).balance, preWithdrawContractBalance);
        assertEq(user.balance, preWithdrawUserBalance);

        // Miner manipulation simulation 2: Try withdraw AT EXACT unlock time
        vm.warp(SAFE_TIMESTAMP_BASE + lockPeriod);
        preWithdrawContractBalance = address(moneyBox).balance;
        preWithdrawUserBalance = user.balance;
        vm.prank(user);
        moneyBox.Collect(depositAmount);
        assertEq(address(moneyBox).balance, preWithdrawContractBalance);
        assertEq(user.balance, preWithdrawUserBalance);

        // Miner manipulation simulation 3: Try withdraw AFTER unlock time
        vm.warp(SAFE_TIMESTAMP_BASE + lockPeriod + 1); // Miner can choose this timestamp
        preWithdrawContractBalance = address(moneyBox).balance;
        preWithdrawUserBalance = user.balance;
        vm.prank(user);
        moneyBox.Collect(depositAmount);
        assertEq(address(moneyBox).balance, preWithdrawContractBalance - depositAmount);
        assertEq(user.balance, preWithdrawUserBalance + depositAmount);
    }
}
